const INDEX_HTML_BASE64 = '';

function decodeHtml() {
  const binary = atob(INDEX_HTML_BASE64);
  const bytes = Uint8Array.from(binary, char => char.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

function normalizeFeedUrl(value) {
  if (!value) return null;
  const normalized = value.replace(/^webcal:\/\//i, 'https://');
  let url;
  try { url = new URL(normalized); } catch { return null; }
  if (url.protocol !== 'https:') return null;
  return url;
}

async function fetchCanvasFeed(request) {
  const requestUrl = new URL(request.url);
  const feedUrl = normalizeFeedUrl(requestUrl.searchParams.get('url'));
  if (!feedUrl) return new Response('Use the full Canvas calendar feed link. It should start with https:// or webcal://.', { status: 400 });
  let response;
  try {
    response = await fetch(feedUrl.toString(), {
      headers: { 'Accept': 'text/calendar,text/plain;q=0.9,*/*;q=0.8', 'User-Agent': 'Campus Planner Canvas Import' },
    });
  } catch (_) {
    return new Response('Canvas could not be reached from the planner server.', { status: 502 });
  }
  if (!response.ok) return new Response('Canvas rejected the calendar feed request with status ' + response.status + '.', { status: 502 });
  const text = await response.text();
  if (!text.includes('BEGIN:VCALENDAR')) return new Response('The link loaded, but it did not look like a Canvas calendar feed.', { status: 422 });
  return new Response(text, {
    headers: { 'content-type': 'text/calendar; charset=utf-8', 'cache-control': 'no-store' },
  });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/api/canvas') return fetchCanvasFeed(request);
    if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Method not allowed', { status: 405 });
    return new Response(decodeHtml(), { headers: { 'content-type': 'text/html; charset=utf-8' } });
  },
};
